final class FaceGeometryParityTests: XCTestCase {
    struct Fixture: Decodable {
        struct Case: Decodable {
            let name: String
            let muscles: [String: Double]
            let blink: Double
            let expected: Expected
        }
        struct Expected: Decodable {
            let smile: Double
            let open_k: Double
            let show_brow: Bool
            let happy_eyes: Bool
            let eye_center_x_right: Double
            let eye_center_y: Double
            let eye_rotation: Double
            let eye_half_height: Double
            let brow_inner_y: Double
            let brow_outer_y: Double
            let mouth_y: Double
            let mouth_half_width: Double
            let mouth_open: Bool
            let mouth_ellipse_center_y: Double
            let mouth_ellipse_ry: Double
            let mouth_curve_end_y: Double
            let mouth_curve_control_y: Double
        }
        let cases: [Case]
    }

    func testFaceGeometryMatchesReference() throws {
        let fixture: Fixture = try loadFixture("face_geometry")
        for c in fixture.cases {
            let g = FaceGeometry(muscles: c.muscles, blink: c.blink)
            let e = c.expected
            XCTAssertEqual(g.smile, e.smile, accuracy: formulaTolerance, c.name)
            XCTAssertEqual(g.openK, e.open_k, accuracy: formulaTolerance, c.name)
            XCTAssertEqual(g.showBrow, e.show_brow, c.name)
            XCTAssertEqual(g.happyEyes, e.happy_eyes, c.name)
            XCTAssertEqual(g.eyeCenterXRight, e.eye_center_x_right, accuracy: formulaTolerance, c.name)
            XCTAssertEqual(g.eyeCenterY, e.eye_center_y, accuracy: formulaTolerance, c.name)
            XCTAssertEqual(g.eyeRotation, e.eye_rotation, accuracy: formulaTolerance, c.name)
            XCTAssertEqual(g.eyeHalfHeight, e.eye_half_height, accuracy: formulaTolerance, c.name)
            XCTAssertEqual(g.browInnerY, e.brow_inner_y, accuracy: formulaTolerance, c.name)
            XCTAssertEqual(g.browOuterY, e.brow_outer_y, accuracy: formulaTolerance, c.name)
            XCTAssertEqual(g.mouthY, e.mouth_y, accuracy: formulaTolerance, c.name)
            XCTAssertEqual(g.mouthHalfWidth, e.mouth_half_width, accuracy: formulaTolerance, c.name)
            XCTAssertEqual(g.mouthOpen, e.mouth_open, c.name)
            XCTAssertEqual(g.mouthEllipseCenterY, e.mouth_ellipse_center_y, accuracy: formulaTolerance, c.name)
            XCTAssertEqual(g.mouthEllipseRy, e.mouth_ellipse_ry, accuracy: formulaTolerance, c.name)
            XCTAssertEqual(g.mouthCurveEndY, e.mouth_curve_end_y, accuracy: formulaTolerance, c.name)
            XCTAssertEqual(g.mouthCurveControlY, e.mouth_curve_control_y, accuracy: formulaTolerance, c.name)
        }
    }
}

final class VoiceParamsParityTests: XCTestCase {
    struct Fixture: Decodable {
        struct Case: Decodable {
            let emotions: [String: Double]
            let rate: Double
            let pitch: Double
        }
        let cases: [Case]
    }

    func testVoiceParamsMatchPython() throws {
        let fixture: Fixture = try loadFixture("voice_params")
        for (i, c) in fixture.cases.enumerated() {
            let e = c.emotions
            let emotions = EmotionVector(
                happiness: e["happiness"]!, excitement: e["excitement"]!,
                anger: e["anger"]!, calm: e["calm"]!,
                bonding: e["bonding"]!, anxiety: e["anxiety"]!,
                sadness: e["sadness"]!, euphoria: e["euphoria"]!
            )
            let params = VoiceParams(emotions: emotions)
            XCTAssertEqual(params.rate, c.rate, accuracy: formulaTolerance, "rate case \(i)")
            XCTAssertEqual(params.pitch, c.pitch, accuracy: formulaTolerance, "pitch case \(i)")
        }
    }
}
